#include "display.h"
#include "dpro_view.hpp"

// DPRO-DENS: generated by tools/make_engine.py. The screen: md_rig.hpp draws the
// design's parts from art.h; voices/dpro_view.hpp draws what changes shape.
namespace mmdens {
inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
    state.header.reset();
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion};
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[0], input.slots, moment);
    md::dpro_dens::view(frame, input.slots, moment);
    // The header last: both pages, the one the encoders edit on its bar.
    static const char* const titles[8] = {"pch2", "pch3", "pch4", "wave", "", "chrl", "chrw", "tune"};
    static const opxy::u8 pages[2][4] = {{0, 1, 2, 3}, {0, 5, 6, 7}};
    char values[8][opxy::draw::header_capacity];
    for (u32 i = 0; i < 8; ++i) md::view::value127(values[i], opxy::draw::header_capacity, input.slots[i]);
    static const char* const steps3[64] = {"D01", "D02", "D03", "D04", "D05", "D06", "D07", "D08", "D09", "D10", "D11", "D12", "D13", "D14", "D15", "D16", "D17", "D18", "D19", "D20", "D21", "D22", "D23", "D24", "D25", "D26", "D27", "D28", "D29", "D30", "D31", "D32", "D33", "D34", "D35", "D36", "D37", "D38", "D39", "D40", "D41", "D42", "D43", "D44", "D45", "D46", "D47", "D48", "D49", "D50", "D51", "D52", "D53", "D54", "D55", "D56", "D57", "D58", "D59", "D60", "D61", "D62", "D63", "D64"};
    opxy::draw::copy(values[3], opxy::draw::header_capacity,
                     steps3[(static_cast<u32>(md::positive(input.slots[3])) >> 16) * 64u >> 15]);
    values[4][0] = 0;
    opxy::draw::page_header(state.header, input, frame, titles, values, header_node, pages);
}
}
